#!/usr/bin/env node
// ---------------------------------------------------------------------------
// Deals seeder — 1,000,000 rows, generated by Postgres.
//
//   node benchmarks/scripts/seed-deals.mjs --deals 1000000
//   node benchmarks/scripts/seed-deals.mjs --deals 1000000 --indexes keep
//
// WHY THE DATABASE GENERATES THE ROWS. The obvious approach is a loop in Node building
// multi-row INSERTs, which is what benchmarks/scripts/seed.mjs does for 1,000 users. At
// 1,000,000 rows that ships every value over a socket, in text format, for data that is
// synthetic anyway — minutes of wire time and JSON-ish encoding to produce numbers nobody
// chose. `INSERT … SELECT … FROM generate_series` produces the same rows entirely inside
// the server: one statement per batch, no round trips, no client memory.
//
// WHY IT IS BATCHED AT ALL, then: one statement for 1M rows is a single transaction
// holding one very large WAL write and an ever-growing snapshot. Batching keeps each
// transaction bounded, lets autovacuum keep up, and makes progress observable — the last
// of which matters more than it sounds when a seed step takes minutes and looks hung.
//
// WHY DETERMINISTIC. `setseed()` fixes the PRNG sequence, so two runs produce identical
// data and a plan difference between two EXPLAIN captures cannot be blamed on different
// rows. Without it, every re-seed is a new dataset and the before/after comparison has an
// uncontrolled variable in it.
//
// INDEX STRATEGY, which is itself one of the numbers being collected. Default is
// `defer`: drop the three deals indexes, bulk load, rebuild them, and report the two
// phases separately. Building an index once over a finished table is a single sort;
// maintaining three btrees while inserting a million rows pays per row and fragments the
// trees. `--indexes keep` measures the other side so the difference is a measurement
// rather than folklore.
// ---------------------------------------------------------------------------
import pg from 'pg';

const args = process.argv.slice(2);
const getArg = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i !== -1 && args[i + 1] ? args[i + 1] : fallback;
};
const hasFlag = (name) => args.includes(`--${name}`);

const TARGET = Number(getArg('deals', 1_000_000));
const BATCH = Number(getArg('batch', 100_000));
const INDEX_STRATEGY = getArg('indexes', 'defer');
const SEED = Number(getArg('seed', 0.4242));
const TRUNCATE = hasFlag('truncate');

const DATABASE_URL = process.env.DATABASE_URL || 'postgresql://bench:bench@localhost:5433/benchdb';

const log = (msg) => process.stdout.write(`[seed-deals] ${msg}\n`);
const secs = (ms) => (ms / 1000).toFixed(1);

/**
 * The row generator.
 *
 * Every column is derived from `g`, the generate_series counter, or from `random()`:
 *
 *   owner_id    indexes into an array of real user ids, collected once in the CTE. The
 *               obvious `(SELECT id FROM users … OFFSET g % n)` would be a correlated
 *               subquery executed a million times.
 *   created_at  spread over a year so the keyset ORDER BY has something to order and the
 *               partial index has a realistic selectivity. Truncated to millisecond
 *               precision to match the column (finding F-46).
 *   stage       weighted: a real pipeline is mostly closed, with a thin open funnel. A
 *               uniform distribution would make the partial index look far better than it
 *               is, which would be measuring the seeder rather than the schema.
 *   closed_at   set only for terminal stages, and always after created_at. The CHECK
 *               constraint `deals_closed_at_matches_stage` rejects any other combination,
 *               so a bug here fails loudly at load time instead of producing data the
 *               application's invariants do not hold for.
 */
const INSERT_BATCH = `
  with owners as (
    select array_agg(id order by id) as ids from users
  ),
  gen as (
    select
      g,
      (now() - (random() * interval '365 days'))::timestamptz(3) as created_at,
      case
        when random() < 0.55 then 'closed_lost'
        when random() < 0.75 then 'closed_won'
        when random() < 0.82 then 'sourced'
        when random() < 0.90 then 'screening'
        when random() < 0.96 then 'diligence'
        else 'negotiation'
      end::deal_stage as stage,
      (random() * 500000000)::bigint as amount_cents
    from generate_series($1::bigint, $2::bigint) as g
  )
  insert into deals (owner_id, title, company, stage, amount_cents, currency, created_at, updated_at, closed_at)
  select
    o.ids[1 + (gen.g % array_length(o.ids, 1))::int],
    'Deal ' || gen.g,
    'Company ' || (gen.g % 5000),
    gen.stage,
    gen.amount_cents,
    case when gen.g % 20 = 0 then 'EUR' else 'USD' end,
    gen.created_at,
    gen.created_at,
    case
      when gen.stage in ('closed_won', 'closed_lost')
      then (gen.created_at + (random() * interval '30 days'))::timestamptz(3)
      else null
    end
  from gen cross join owners o
`;

async function requireSchema(client) {
  const { rows } = await client.query(`select to_regclass('deals') is not null as present`);
  if (!rows[0].present) {
    // Deliberately NOT created here, unlike the users table in seed.mjs. That table is
    // seven plain columns; this one carries an enum, three CHECK constraints, a foreign
    // key and three indexes, and a hand-copy in a seeder is a second definition that will
    // drift from drizzle/0001_deals.sql without anyone noticing.
    throw new Error('deals table is missing — run `npm run db:migrate` first');
  }
  const { rows: users } = await client.query('select count(*)::int as n from users');
  if (users[0].n === 0) {
    throw new Error('no users to own deals — run `npm run bench:seed` first');
  }
  return users[0].n;
}

/**
 * Read the index definitions back out of the catalogue before dropping them.
 *
 * `pg_indexes.indexdef` is the definitive CREATE INDEX statement for what actually exists,
 * so a rebuild replays reality rather than a copy of the migration that may have drifted.
 * It also means this script needs no knowledge of the schema it is loading.
 */
async function captureIndexes(client) {
  const { rows } = await client.query(
    `select indexname, indexdef from pg_indexes
      where tablename = 'deals' and indexname <> 'deals_pkey'
      order by indexname`
  );
  return rows;
}

async function main() {
  log(`target: ${DATABASE_URL.replace(/(:\/\/[^:]+:)[^@]+@/, '$1***@')}`);
  log(`deals: ${TARGET}, batch: ${BATCH}, indexes: ${INDEX_STRATEGY}, seed: ${SEED}`);

  const client = new pg.Client({ connectionString: DATABASE_URL });
  await client.connect();

  try {
    const userCount = await requireSchema(client);
    log(`owners available: ${userCount}`);

    if (TRUNCATE) {
      // TRUNCATE, not DELETE: no per-row work, no dead tuples for autovacuum to reclaim,
      // and it resets the sequence so ids are comparable between runs.
      await client.query('truncate table deals restart identity');
      log('truncated deals');
    }

    const { rows: existing } = await client.query('select count(*)::int as n from deals');
    if (existing[0].n >= TARGET) {
      log(`already seeded (${existing[0].n} rows) — pass --truncate to reload`);
      await report(client);
      return;
    }

    // Fix the PRNG for the session so two runs produce identical data.
    await client.query('select setseed($1)', [SEED]);

    let indexes = [];
    if (INDEX_STRATEGY === 'defer') {
      indexes = await captureIndexes(client);
      const t = Date.now();
      for (const idx of indexes) await client.query(`drop index ${idx.indexname}`);
      log(
        `dropped ${indexes.length} indexes in ${secs(Date.now() - t)}s — they are rebuilt after the load`
      );
      log(
        `  if this process dies before then, rebuild with:\n${indexes.map((i) => `    ${i.indexdef};`).join('\n')}`
      );
    }

    const start = existing[0].n + 1;
    const tLoad = Date.now();
    let inserted = 0;

    for (let from = start; from <= TARGET; from += BATCH) {
      const to = Math.min(from + BATCH - 1, TARGET);
      const tBatch = Date.now();
      const res = await client.query(INSERT_BATCH, [from, to]);
      inserted += res.rowCount;
      const rate = res.rowCount / ((Date.now() - tBatch) / 1000);
      log(`${to}/${TARGET} rows (${rate.toFixed(0)} rows/s this batch)`);
    }

    const loadMs = Date.now() - tLoad;
    log(
      `LOAD: ${inserted} rows in ${secs(loadMs)}s = ${(inserted / (loadMs / 1000)).toFixed(0)} rows/s`
    );

    let indexMs = 0;
    if (INDEX_STRATEGY === 'defer' && indexes.length > 0) {
      const tIdx = Date.now();
      for (const idx of indexes) {
        const t = Date.now();
        await client.query(idx.indexdef);
        log(`  built ${idx.indexname} in ${secs(Date.now() - t)}s`);
      }
      indexMs = Date.now() - tIdx;
      log(`INDEX BUILD: ${indexes.length} indexes in ${secs(indexMs)}s`);
      log(
        `TOTAL: ${secs(loadMs + indexMs)}s — compare against a --indexes keep run, where the ` +
          'same work is paid per row during the load'
      );
    }

    // ANALYZE, and it is not optional. The planner chooses between an index scan and a
    // sequential scan from `pg_statistic`; on a freshly loaded table those statistics
    // describe an empty one. Skipping this is the most common way to benchmark a bad plan
    // and then blame the schema — and it is also why `reltuples` (F-45) is -1 until it runs.
    const tAnalyze = Date.now();
    await client.query('analyze deals');
    log(`ANALYZE in ${secs(Date.now() - tAnalyze)}s — planner statistics refreshed`);

    await report(client);
  } finally {
    await client.end();
  }
}

async function report(client) {
  const { rows: byStage } = await client.query(
    `select stage, count(*)::int as n, count(closed_at)::int as closed
       from deals group by stage order by n desc`
  );
  log('distribution:');
  for (const r of byStage)
    log(
      `  ${String(r.stage).padEnd(13)} ${String(r.n).padStart(8)} rows (closed_at set: ${r.closed})`
    );

  const { rows: size } = await client.query(
    `select pg_size_pretty(pg_table_size('deals')) as heap,
            pg_size_pretty(pg_indexes_size('deals')) as indexes,
            (select reltuples::bigint from pg_class where relname = 'deals') as reltuples`
  );
  log(
    `heap: ${size[0].heap}, indexes: ${size[0].indexes}, reltuples estimate: ${size[0].reltuples}`
  );

  const { rows: idx } = await client.query(
    `select indexname from pg_indexes where tablename = 'deals' order by indexname`
  );
  log(`indexes present: ${idx.map((r) => r.indexname).join(', ') || '(none)'}`);
}

main().catch((e) => {
  process.stderr.write(`[seed-deals] FAILED: ${e.message}\n`);
  process.exit(1);
});
